"use client";

import { SettingsForm, ToggleField } from "./fields";

/**
 * Exit-intent discount popup controls. When a signed-in, first-time customer
 * (zero non-free `Server` rows — the same predicate `firstTimeOnly` coupon
 * enforcement already uses in lib/order.ts) moves their mouse toward the
 * browser chrome while on the deploy wizard's pricing step, they're shown a
 * one-time 25%-off nudge (components/nx/ExitIntentModal.tsx). Saves through
 * the shared `saveSettings` action (section "exit_intent"), exactly like
 * every other panel here.
 */
export function ExitIntentPanel({ v }: { v: Record<string, string> }) {
  return (
    <SettingsForm
      section="exit_intent"
      title="Exit-intent discount popup"
      desc="Shows first-time customers a one-time 25% off nudge when they move to leave the deploy wizard's pricing step. Reuses the real coupon engine (code EXIT25) — nothing charges differently than typing the code in by hand."
    >
      <ToggleField
        label="Enable exit-intent popup"
        name="exit_intent_enabled"
        defaultChecked={v.exit_intent_enabled === "true"}
        hint="Requires the EXIT25 coupon to exist and be active, or “Claim now” will fail validation."
      />
    </SettingsForm>
  );
}
