// Status notices — the premade, customer-facing notice catalog plus the pure
// helpers around it (visibility, region filtering, queue-depth suggestion).
//
// PLAIN DATA + PURE FUNCTIONS ONLY. No I/O, no db import: this file is imported by
// client components (the admin preview, the customer notice), by the server
// actions and by the tests, and must stay safe in all three. The persistence layer
// is lib/status-notices-core.ts (store-injected) and lib/actions-status-notices.ts.
//
// A notice is information only. Nothing here, or anywhere it is used, blocks an
// order. Wording rules (enforced by test/status-notices.test.ts): Nxeon speaks as
// the owner, so no mention of a third party running our infrastructure; plain and
// calm; no invented numbers or ETAs, so no digits in any preset text at all.

import { CUSTOMER_REGION_LABELS } from "./node-regions";

export const NOTICE_LEVELS = ["INFO", "SUCCESS", "WARNING", "CRITICAL"] as const;
export type NoticeLevel = (typeof NOTICE_LEVELS)[number];

export const NOTICE_PLACEMENTS = ["dashboard", "deploy", "both"] as const;
export type NoticePlacement = (typeof NOTICE_PLACEMENTS)[number];

export const NOTICE_CATEGORIES = ["deployments", "platform", "billing", "maintenance", "support", "positive", "custom"] as const;
export type NoticeCategory = (typeof NOTICE_CATEGORIES)[number];

export const CATEGORY_LABEL: Record<NoticeCategory, string> = {
  deployments: "Deployments",
  platform: "Platform",
  billing: "Billing",
  maintenance: "Maintenance",
  support: "Support",
  positive: "All clear",
  custom: "Custom",
};

/** Hard length caps for stored text (admin overrides included). */
export const TITLE_MAX = 120;
export const BODY_MAX = 600;
/** Caps the catalog's own text must stay under (shorter than what an admin may write). */
export const PRESET_TITLE_MAX = 70;
export const PRESET_BODY_MAX = 330;

/** The longest an auto-off timer may be, in hours (30 days). */
export const MAX_DURATION_HOURS = 24 * 30;

export type NoticePreset = {
  /** Stable forever: it is the Announcement.templateKey unique key. Never rename. */
  key: string;
  /** Admin-facing name on the card. */
  label: string;
  category: NoticeCategory;
  level: NoticeLevel;
  /** Customer-facing. */
  title: string;
  body: string;
  placement: NoticePlacement;
  /** null = stays on until an admin switches it off. */
  defaultDurationHours: number | null;
  dismissible: boolean;
  /** Region key (Node.region): only shown in the deploy flow while that region is selected. */
  region?: string;
  /** Only shown when the order in progress is one of these services. */
  services?: ("vps" | "game")[];
  /**
   * What the "your server is being set up" screen says instead of title + body.
   * A string replaces them, `false` hides the notice there, undefined shows title + body.
   */
  setup?: string | false;
  /** True when the body carries a `{window}` slot the admin fills in (maintenance). */
  hasWindow?: boolean;
};

const SETUP_SLOW =
  "Your server is being set up. Deployments are taking longer than usual right now, this is expected.";

/** Region presets are generated from the real region codes so a label can never drift from the wizard's. */
const REGION_PRESET_CODES = ["sgp1", "bhs1", "fsn1"] as const;

function regionPresets(): NoticePreset[] {
  return REGION_PRESET_CODES.map((code) => {
    const name = CUSTOMER_REGION_LABELS[code] ?? code;
    return {
      key: `region-capacity-${code}`,
      label: `${name} at capacity`,
      category: "deployments" as const,
      level: "WARNING" as const,
      title: `${name} is at capacity`,
      body: `New orders in ${name} are limited right now. You can choose another location, or come back a little later.`,
      placement: "deploy" as const,
      defaultDurationHours: null,
      dismissible: false,
      region: code,
      setup: false as const,
    };
  });
}

const BASE_PRESETS: NoticePreset[] = [
  // ---- Deployments ---------------------------------------------------------
  {
    key: "high-deployment-volume",
    label: "High deployment volume",
    category: "deployments",
    level: "INFO",
    title: "High deployment volume right now",
    body: "A lot of servers are being deployed at the moment, so setup may take a few extra minutes. Your order is safe and will complete as normal.",
    placement: "both",
    defaultDurationHours: 4,
    dismissible: true,
    setup: SETUP_SLOW,
  },
  {
    key: "provisioning-slower",
    label: "Provisioning slower than usual",
    category: "deployments",
    level: "WARNING",
    title: "Provisioning is slower than usual",
    body: "New servers are taking longer than usual to come online. Orders are still being processed and nothing needs to be redone. You can follow progress on your server page.",
    placement: "both",
    defaultDurationHours: 4,
    dismissible: false,
    setup: SETUP_SLOW,
  },
  {
    key: "game-deployments-delayed",
    label: "Game server deployments delayed",
    category: "deployments",
    level: "WARNING",
    title: "Game server deployments are delayed",
    body: "Game servers are taking longer than usual to set up, because the game files need extra time to install. Your server will start on its own once it is ready.",
    placement: "both",
    defaultDurationHours: 4,
    dismissible: false,
    services: ["game"],
    setup: "Your game server is being set up. Game deployments are taking longer than usual right now, this is expected.",
  },
  {
    key: "region-capacity",
    label: "Region at capacity (any region)",
    category: "deployments",
    level: "WARNING",
    title: "Some locations are at capacity",
    body: "New orders are limited in one or more locations right now. If your preferred location is unavailable, please choose another nearby location or check back soon.",
    placement: "deploy",
    defaultDurationHours: null,
    dismissible: false,
    setup: false,
  },
  ...regionPresets(),
  {
    key: "deployments-paused",
    label: "Deployments paused briefly",
    category: "deployments",
    level: "CRITICAL",
    title: "Deployments are paused for a short time",
    body: "We have paused new deployments briefly while we complete some work. Servers that are already running are not affected by this pause. Check back shortly, or watch this notice for an update.",
    placement: "both",
    defaultDurationHours: 2,
    dismissible: false,
    setup: "Your server is being set up. New deployments were paused briefly, so this may take longer than usual.",
  },

  // ---- Platform ------------------------------------------------------------
  {
    key: "investigating-issue",
    label: "We are investigating an issue",
    category: "platform",
    level: "WARNING",
    title: "We are investigating an issue",
    body: "We are looking into an issue that may affect some services. We will update this notice as soon as we have more information.",
    placement: "both",
    defaultDurationHours: null,
    dismissible: true,
  },
  {
    key: "degraded-performance",
    label: "Degraded performance",
    category: "platform",
