}

/** Live right now = active and inside its optional [startsAt, expiresAt) window. */
export function isLive(
  row: { active: boolean; startsAt: Date | null; expiresAt: Date | null },
  now: Date,
): boolean {
  if (!row.active) return false;
  if (row.startsAt && row.startsAt > now) return false;
  if (row.expiresAt && row.expiresAt <= now) return false;
  return true;
}

// ---------- Customer-facing shape ----------------------------------------------

export type CustomerNotice = {
  id: string;
  key: string | null;
  level: NoticeLevel;
  title: string;
  body: string | null;
  placement: NoticePlacement;
  dismissible: boolean;
  region: string | null;
  /** From the catalog by key; null for custom/legacy rows. */
  services: ("vps" | "game")[] | null;
  /** string = replacement text, false = hide on the setup screen, null = show title + body. */
  setup: string | false | null;
};

export function asLevel(v: string): NoticeLevel {
  return (NOTICE_LEVELS as readonly string[]).includes(v) ? (v as NoticeLevel) : "INFO";
}
export function asPlacement(v: string): NoticePlacement {
  return (NOTICE_PLACEMENTS as readonly string[]).includes(v) ? (v as NoticePlacement) : "dashboard";
}

type RowLike = {
  id: string;
  templateKey: string | null;
  level: string;
  title: string;
  body: string | null;
  placement: string;
  dismissible: boolean;
  region: string | null;
};

export function toCustomerNotice(r: RowLike): CustomerNotice {
  const preset = r.templateKey ? presetByKey(r.templateKey) : null;
  return {
    id: r.id,
    key: r.templateKey,
    level: asLevel(r.level),
    title: r.title,
    body: r.body,
    placement: asPlacement(r.placement),
    // Re-derive from the catalog rule so a stale row can never show a dismiss button it must not have.
    dismissible: effectiveDismissible(preset?.category ?? "custom", r.level, r.dismissible),
    region: r.region,
    services: preset?.services ?? null,
    setup: preset ? (preset.setup === undefined ? null : preset.setup) : null,
  };
}

/** Which notices to show in the order flow, given the order in progress. */
export function noticesForDeploy(
  all: CustomerNotice[],
  ctx: { region?: string | null; service?: string | null },
): CustomerNotice[] {
  return all.filter((n) => {
    if (n.placement === "dashboard") return false;
    if (n.region && n.region !== ctx.region) return false;
    if (n.services && (!ctx.service || !(n.services as string[]).includes(ctx.service))) return false;
    return true;
  });
}

/** Which notices the "your server is being set up" screen should add, as title/body pairs. */
export function noticesForSetup(
  all: CustomerNotice[],
  ctx: { region?: string | null; service?: string | null },
): { id: string; level: NoticeLevel; title: string; body: string | null }[] {
  return noticesForDeploy(all, ctx)
    .filter((n) => n.setup !== false)
    .map((n) =>
      typeof n.setup === "string"
        ? { id: n.id, level: n.level, title: n.setup, body: null }
        : { id: n.id, level: n.level, title: n.title, body: n.body },
    );
}

// ---------- Admin "Right now" hint ---------------------------------------------

export type QueueHint = {
  /** PROVISION jobs that are QUEUED or RUNNING. */
  active: number;
  queued: number;
  running: number;
  /** Age in whole minutes of the oldest QUEUED provision job; null when none is queued. */
  oldestQueuedMinutes: number | null;
};

export type SuggestSettings = {
  enabled: boolean;
  /** Suggest when queued + running reaches this. */
  queueThreshold: number;
  /** Suggest when the oldest queued job is at least this many minutes old. */
  ageMinutes: number;
};

export const SUGGEST_DEFAULTS: SuggestSettings = { enabled: false, queueThreshold: 10, ageMinutes: 10 };

/**
 * Which Deployments preset to highlight, or null. Highlight only: nothing is ever switched on
 * by this. A wait three times the age threshold points at the stronger wording.
 */
export function suggestPreset(hint: QueueHint, s: SuggestSettings): string | null {
  if (!s.enabled) return null;
  const age = hint.oldestQueuedMinutes ?? 0;
  if (age >= s.ageMinutes * 3) return "provisioning-slower";
  if (hint.active >= s.queueThreshold || age >= s.ageMinutes) return "high-deployment-volume";
  return null;
}

export function minutesBetween(from: Date, to: Date): number {
  return Math.max(0, Math.floor((to.getTime() - from.getTime()) / 60_000));
}

