// Status notices — persistence logic, with the database and audit log INJECTED.
//
// Why injected: lib/actions-status-notices.ts is the only place that touches
// `db`/auth, and this repo's tests never import a module that connects to Prisma
// (see test/api-http-surface.test.ts). Everything that decides what a toggle DOES
// lives here against a small store interface, so the tests drive the real logic
// with an in-memory fake. The server actions are thin: authorize, build the real
// store, call in here.

import {
  BODY_MAX,
  TITLE_MAX,
  NOTICE_LEVELS,
  NOTICE_PLACEMENTS,
  effectiveDismissible,
  expiryFromDuration,
  isLive,
  minutesBetween,
  normalizeDuration,
  presetByKey,
  renderBody,
  suggestPreset,
  type NoticePreset,
  type QueueHint,
  type SuggestSettings,
} from "./status-notices";

export type NoticeRow = {
  id: string;
  templateKey: string | null;
  title: string;
  body: string | null;
  level: string;
  active: boolean;
  startsAt: Date | null;
  expiresAt: Date | null;
  placement: string;
  dismissible: boolean;
  region: string | null;
  customText: boolean;
  switchedBy: string | null;
  switchedAt: Date | null;
  createdBy: string | null;
};

/** Fields an upsert may write. `createdBy` is only ever written on create. */
export type NoticeWrite = Omit<NoticeRow, "id" | "templateKey" | "createdBy">;

export interface NoticeStore {
  findByKey(key: string): Promise<NoticeRow | null>;
  /**
   * Atomic create-or-update on the unique templateKey. Two concurrent switches of the same
   * notice must end as one row (the real implementation upserts, and on a lost create race
   * retries as an update).
   */
  upsertByKey(key: string, create: NoticeWrite & { createdBy: string }, update: Partial<NoticeWrite>): Promise<NoticeRow>;
  listTemplateRows(): Promise<NoticeRow[]>;
  userNames(ids: string[]): Promise<Record<string, string>>;
  provisionQueue(): Promise<{ queued: number; running: number; oldestQueuedAt: Date | null }>;
}

export type NoticeDeps = {
  store: NoticeStore;
  /** The shared audit writer (lib/audit.ts recordAudit) in production. */
  audit: (actorId: string, action: string, detail: string) => Promise<void>;
  now: () => Date;
};

export type Actor = { id: string };
export type NoticeResult = { ok: true; row: NoticeRow; changed: boolean } | { ok: false; error: string };

export type SwitchOnOptions = {
  /** undefined = the preset's default; null or 0 = until switched off. */
  hours?: number | null;
  /** Override the text (kept for this notice from then on). */
  title?: string;
  body?: string;
  /** Maintenance presets: fills the `{window}` slot of the catalog body. */
  windowText?: string;
  /** Custom notice only. */
  level?: string;
  placement?: string;
  region?: string | null;
  dismissible?: boolean;
};

// ---------- text ---------------------------------------------------------------

export function validateText(titleIn: unknown, bodyIn: unknown): { title: string; body: string } | { error: string } {
  const title = String(titleIn ?? "").trim();
  const body = String(bodyIn ?? "").trim();
  if (!title) return { error: "Enter a title." };
  if (title.length > TITLE_MAX) return { error: `Title is too long (max ${TITLE_MAX} characters).` };
  if (body.length > BODY_MAX) return { error: `Message is too long (max ${BODY_MAX} characters).` };
  return { title, body };
}

/** The catalog text for a preset, `{window}` filled. */
function defaultText(p: NoticePreset, windowText?: string | null) {
  return { title: p.title, body: renderBody(p.body, windowText) };
}

// ---------- switching ----------------------------------------------------------

export async function switchNoticeOn(
  deps: NoticeDeps,
  actor: Actor,
  key: string,
  opts: SwitchOnOptions = {},
): Promise<NoticeResult> {
  const preset = presetByKey(key);
  if (!preset) return { ok: false, error: "Unknown notice." };
  const now = deps.now();
  const existing = await deps.store.findByKey(key);
  const isCustom = preset.category === "custom";

  // Text: explicit override > window fill > text kept from an earlier edit > catalog text.
  let text: { title: string; body: string };
  let customText: boolean;
  if (opts.title !== undefined || opts.body !== undefined) {
    const v = validateText(opts.title ?? existing?.title ?? preset.title, opts.body ?? existing?.body ?? "");
    if ("error" in v) return { ok: false, error: v.error };
    text = v;
    customText = true;
  } else if (preset.hasWindow && opts.windowText && opts.windowText.trim()) {
    text = defaultText(preset, opts.windowText);
    if (text.body.length > BODY_MAX) return { ok: false, error: `Window text is too long.` };
    customText = true; // stored literally so a later switch-on keeps the window
  } else if (existing?.customText) {
    text = { title: existing.title, body: existing.body ?? "" };
    customText = true;
  } else {
    text = defaultText(preset);
    customText = false;
  }
  if (isCustom && customText === false) {
    // A custom notice with no text of its own would publish the placeholder sentence.
    return { ok: false, error: "Write the title and message for a custom notice first." };
  }

  // Level / placement / region / dismissible are fixed by the catalog; only Custom is free.
  let level = preset.level as string;
  let placement = preset.placement as string;
  let region: string | null = preset.region ?? null;
  let dismissWanted = preset.dismissible;
  if (isCustom) {
    level = (NOTICE_LEVELS as readonly string[]).includes(opts.level ?? "") ? (opts.level as string) : existing?.level ?? "INFO";
    placement = (NOTICE_PLACEMENTS as readonly string[]).includes(opts.placement ?? "") ? (opts.placement as string) : existing?.placement ?? "dashboard";
    region = opts.region === undefined ? existing?.region ?? null : opts.region || null;
    dismissWanted = opts.dismissible ?? existing?.dismissible ?? true;
  }
  const dismissible = effectiveDismissible(preset.category, level, dismissWanted);

  const hours = opts.hours === undefined ? preset.defaultDurationHours : normalizeDuration(opts.hours);
  const expiresAt = expiryFromDuration(now, hours);

  const write: NoticeWrite = {
    title: text.title.slice(0, TITLE_MAX),
    body: text.body ? text.body.slice(0, BODY_MAX) : null,
    level,
    active: true,
    startsAt: null,
    expiresAt,
    placement,
    dismissible,
    region,
    customText,
    switchedBy: actor.id,
    switchedAt: now,
  };
  const wasLive = existing ? isLive(existing, now) : false;
  const row = await deps.store.upsertByKey(key, { ...write, createdBy: actor.id }, write);
  await deps.audit(
    actor.id,
    "admin.status_notice_on",
    `key=${key} expires=${expiresAt ? expiresAt.toISOString() : "never"} placement=${placement}${wasLive ? " (already on, refreshed)" : ""}`,
  );
  return { ok: true, row, changed: !wasLive };
}

export async function switchNoticeOff(deps: NoticeDeps, actor: Actor, key: string): Promise<NoticeResult> {
  const preset = presetByKey(key);
  if (!preset) return { ok: false, error: "Unknown notice." };
  const now = deps.now();
  const existing = await deps.store.findByKey(key);
  if (!existing) {
    // Never switched on: nothing to turn off. Still audited, so every toggle request is on record.
    await deps.audit(actor.id, "admin.status_notice_off", `key=${key} (was not on)`);
    return { ok: false, error: "That notice is not on." };
  }
  const wasLive = isLive(existing, now);
  // Keep the row (history, kept text); only the switch changes. `changed` is false when already off.
  const row = existing.active
    ? await deps.store.upsertByKey(key, { ...rowToWrite(existing), createdBy: actor.id }, { active: false, switchedBy: actor.id, switchedAt: now })
    : existing;
  await deps.audit(actor.id, "admin.status_notice_off", `key=${key}${existing.active ? "" : " (already off)"}${wasLive ? "" : existing.active ? " (had expired)" : ""}`);
  return { ok: true, row, changed: existing.active };
}

function rowToWrite(r: NoticeRow): NoticeWrite {
  const { id: _id, templateKey: _k, createdBy: _c, ...rest } = r;
  void _id; void _k; void _c;
  return rest;
}

/**
 * Save the wording for a notice WITHOUT switching it on (edit-before-enabling). Creates the
 * row switched off if there isn't one. `reset` goes back to the catalog text.
 */
export async function saveNoticeText(
  deps: NoticeDeps,
  actor: Actor,
  key: string,
  input: { title?: string; body?: string; reset?: boolean },
): Promise<NoticeResult> {
  const preset = presetByKey(key);
  if (!preset) return { ok: false, error: "Unknown notice." };
  const existing = await deps.store.findByKey(key);
  let text: { title: string; body: string };
  let customText: boolean;
  if (input.reset) {
    if (preset.category === "custom") return { ok: false, error: "A custom notice has no default text to reset to." };
    text = defaultText(preset);
    customText = false;
  } else {
    const v = validateText(input.title, input.body);
    if ("error" in v) return { ok: false, error: v.error };
    text = v;
    customText = true;
  }
  const now = deps.now();
  const base: NoticeWrite = existing
    ? rowToWrite(existing)
    : {
        title: text.title, body: null, level: preset.level, active: false, startsAt: null, expiresAt: null,
        placement: preset.placement, dismissible: effectiveDismissible(preset.category, preset.level, preset.dismissible),
        region: preset.region ?? null, customText: false, switchedBy: null, switchedAt: null,
      };
  const update: Partial<NoticeWrite> = { title: text.title, body: text.body || null, customText };
  const row = await deps.store.upsertByKey(key, { ...base, ...update, createdBy: actor.id }, update);
  await deps.audit(actor.id, "admin.status_notice_edit", `key=${key} ${input.reset ? "reset to default text" : "custom text saved"} at=${now.toISOString()}`);
  return { ok: true, row, changed: true };
}

// ---------- reading for the admin UI -------------------------------------------

export type NoticeCardState = {
  key: string;
  /** on = live now; off = switched off or never on; expired = was on, timer ran out. */
  state: "on" | "off" | "expired";
  title: string;
  body: string;
  customized: boolean;
  expiresAt: string | null;
  switchedAt: string | null;
  switchedByName: string | null;
  /** Stored settings of a Custom notice, so the editor can reopen with them. */
  level: string;
  placement: string;
  region: string | null;
  dismissible: boolean;
};

export async function listNoticeStates(deps: NoticeDeps): Promise<Record<string, NoticeCardState>> {
  const now = deps.now();
  const rows = await deps.store.listTemplateRows();
  const names = await deps.store.userNames([...new Set(rows.map((r) => r.switchedBy).filter((x): x is string => !!x))]);
  const out: Record<string, NoticeCardState> = {};
  for (const r of rows) {
    if (!r.templateKey || !presetByKey(r.templateKey)) continue;
    const live = isLive(r, now);
    out[r.templateKey] = {
      key: r.templateKey,
      state: live ? "on" : r.active && r.expiresAt && r.expiresAt <= now ? "expired" : "off",
      title: r.title,
      body: r.body ?? "",
      customized: r.customText,
      expiresAt: r.expiresAt ? r.expiresAt.toISOString() : null,
      switchedAt: r.switchedAt ? r.switchedAt.toISOString() : null,
      switchedByName: r.switchedBy ? names[r.switchedBy] ?? null : null,
      level: r.level,
      placement: r.placement,
      region: r.region,
      dismissible: r.dismissible,
    };
  }
  return out;
}

/** The "Right now" numbers beside the Deployments presets. Read-only. */
export async function queueHint(deps: NoticeDeps): Promise<QueueHint> {
  const q = await deps.store.provisionQueue();
  return {
    active: q.queued + q.running,
    queued: q.queued,
    running: q.running,
    oldestQueuedMinutes: q.oldestQueuedAt ? minutesBetween(q.oldestQueuedAt, deps.now()) : null,
  };
}

export { suggestPreset };
export type { SuggestSettings };

