/**
 * Save the wording for a notice WITHOUT switching it on (edit-before-enabling). Creates the
 * row switched off if there isn't one. `reset` goes back to the catalog text.
 */
export async function saveNoticeText(
  deps: NoticeDeps,
  actor: Actor,
  key: string,
  input: { title?: string; body?: string; reset?: boolean },
): Promise<NoticeResult> {
  const preset = presetByKey(key);
  if (!preset) return { ok: false, error: "Unknown notice." };
  const existing = await deps.store.findByKey(key);
  let text: { title: string; body: string };
  let customText: boolean;
  if (input.reset) {
    if (preset.category === "custom") return { ok: false, error: "A custom notice has no default text to reset to." };
    text = defaultText(preset);
    customText = false;
  } else {
    const v = validateText(input.title, input.body);
    if ("error" in v) return { ok: false, error: v.error };
    text = v;
    customText = true;
  }
  const now = deps.now();
  const base: NoticeWrite = existing
    ? rowToWrite(existing)
    : {
        title: text.title, body: null, level: preset.level, active: false, startsAt: null, expiresAt: null,
        placement: preset.placement, dismissible: effectiveDismissible(preset.category, preset.level, preset.dismissible),
        region: preset.region ?? null, customText: false, switchedBy: null, switchedAt: null,
      };
  const update: Partial<NoticeWrite> = { title: text.title, body: text.body || null, customText };
  const row = await deps.store.upsertByKey(key, { ...base, ...update, createdBy: actor.id }, update);
  await deps.audit(actor.id, "admin.status_notice_edit", `key=${key} ${input.reset ? "reset to default text" : "custom text saved"} at=${now.toISOString()}`);
  return { ok: true, row, changed: true };
}

// ---------- reading for the admin UI -------------------------------------------

export type NoticeCardState = {
  key: string;
  /** on = live now; off = switched off or never on; expired = was on, timer ran out. */
  state: "on" | "off" | "expired";
  title: string;
  body: string;
  customized: boolean;
  expiresAt: string | null;
  switchedAt: string | null;
  switchedByName: string | null;
  /** Stored settings of a Custom notice, so the editor can reopen with them. */
  level: string;
  placement: string;
  region: string | null;
  dismissible: boolean;
};

export async function listNoticeStates(deps: NoticeDeps): Promise<Record<string, NoticeCardState>> {
  const now = deps.now();
  const rows = await deps.store.listTemplateRows();
  const names = await deps.store.userNames([...new Set(rows.map((r) => r.switchedBy).filter((x): x is string => !!x))]);
  const out: Record<string, NoticeCardState> = {};
  for (const r of rows) {
    if (!r.templateKey || !presetByKey(r.templateKey)) continue;
    const live = isLive(r, now);
    out[r.templateKey] = {
      key: r.templateKey,
      state: live ? "on" : r.active && r.expiresAt && r.expiresAt <= now ? "expired" : "off",
      title: r.title,
      body: r.body ?? "",
      customized: r.customText,
      expiresAt: r.expiresAt ? r.expiresAt.toISOString() : null,
      switchedAt: r.switchedAt ? r.switchedAt.toISOString() : null,
      switchedByName: r.switchedBy ? names[r.switchedBy] ?? null : null,
      level: r.level,
      placement: r.placement,
      region: r.region,
      dismissible: r.dismissible,
    };
  }
  return out;
}

/** The "Right now" numbers beside the Deployments presets. Read-only. */
export async function queueHint(deps: NoticeDeps): Promise<QueueHint> {
  const q = await deps.store.provisionQueue();
  return {
    active: q.queued + q.running,
    queued: q.queued,
    running: q.running,
    oldestQueuedMinutes: q.oldestQueuedAt ? minutesBetween(q.oldestQueuedAt, deps.now()) : null,
  };
}

export { suggestPreset };
export type { SuggestSettings };

