// Real database + audit wiring for lib/status-notices-core.ts. Server-only (imports db).
// Not a "use server" module: nothing here is a public endpoint; the actions in
// lib/actions-status-notices.ts authorize first and then build deps from here.

import { db } from "./db";
import { recordAudit } from "./audit";
import { SETTINGS_DEFAULTS, getSetting } from "./settings";
import { SUGGEST_DEFAULTS, type SuggestSettings } from "./status-notices";
import type { NoticeDeps, NoticeRow, NoticeStore, NoticeWrite } from "./status-notices-core";

const SELECT = {
  id: true, templateKey: true, title: true, body: true, level: true, active: true, startsAt: true,
  expiresAt: true, placement: true, dismissible: true, region: true, customText: true,
  switchedBy: true, switchedAt: true, createdBy: true,
} as const;

export const dbNoticeStore: NoticeStore = {
  findByKey: (key) => db.announcement.findUnique({ where: { templateKey: key }, select: SELECT }),

  async upsertByKey(key, create, update) {
    try {
      return await db.announcement.upsert({
        where: { templateKey: key },
        create: { ...create, templateKey: key },
        update,
        select: SELECT,
      });
    } catch (e) {
      // Two admins switching the same notice at the same instant: both saw "no row", one create
      // won the unique key. The loser's data is equivalent, so apply it as a plain update.
      if ((e as { code?: string })?.code === "P2002") {
        return db.announcement.update({ where: { templateKey: key }, data: update, select: SELECT });
      }
      throw e;
    }
  },

  listTemplateRows: () => db.announcement.findMany({ where: { templateKey: { not: null } }, select: SELECT }),

  async userNames(ids) {
    if (ids.length === 0) return {};
    const users = await db.user.findMany({ where: { id: { in: ids } }, select: { id: true, name: true } });
    return Object.fromEntries(users.map((u) => [u.id, u.name]));
  },

  async provisionQueue() {
    const [queued, running, oldest] = await Promise.all([
      db.job.count({ where: { type: "PROVISION", status: "QUEUED" } }),
      db.job.count({ where: { type: "PROVISION", status: "RUNNING" } }),
      db.job.findFirst({ where: { type: "PROVISION", status: "QUEUED" }, orderBy: { createdAt: "asc" }, select: { createdAt: true } }),
    ]);
    return { queued, running, oldestQueuedAt: oldest?.createdAt ?? null };
  },
};

export function realNoticeDeps(): NoticeDeps {
  return {
    store: dbNoticeStore,
    audit: (actorId, action, detail) => recordAudit(actorId, action, detail),
    now: () => new Date(),
  };
}

/** Admin-tunable suggestion thresholds (settings status_notice_auto_suggest*). Never switches anything on. */
export async function readSuggestSettings(): Promise<SuggestSettings> {
  const [en, q, a] = await Promise.all([
    getSetting("status_notice_auto_suggest"),
    getSetting("status_notice_suggest_queue"),
    getSetting("status_notice_suggest_age_min"),
  ]);
  const num = (raw: string, fb: number) => {
    const n = Number(raw);
    return Number.isFinite(n) && n > 0 ? n : fb;
  };
  return {
    enabled: (en || SETTINGS_DEFAULTS.status_notice_auto_suggest) === "true",
    queueThreshold: num(q, SUGGEST_DEFAULTS.queueThreshold),
    ageMinutes: num(a, SUGGEST_DEFAULTS.ageMinutes),
  };
}
