export async function liveNotices(placements: ("dashboard" | "deploy" | "both")[], opts: { take?: number } = {}): Promise<CustomerNotice[]> {
  const now = new Date();
  const rows = await db.announcement.findMany({
    where: {
      active: true,
      placement: { in: placements },
      AND: [
        { OR: [{ startsAt: null }, { startsAt: { lte: now } }] },
        { OR: [{ expiresAt: null }, { expiresAt: { gt: now } }] },
      ],
    },
    orderBy: { createdAt: "desc" },
    take: opts.take ?? 10,
    select: { id: true, templateKey: true, level: true, title: true, body: true, placement: true, dismissible: true, region: true },
  });
