"use server";

import { revalidatePath } from "next/cache";
import { requireArea } from "./rbac";
import { SUGGEST_DEFAULTS, suggestPreset, type QueueHint } from "./status-notices";
import {
  listNoticeStates,
  queueHint,
  saveNoticeText,
  switchNoticeOff,
  switchNoticeOn,
  type NoticeCardState,
  type SwitchOnOptions,
} from "./status-notices-core";
import { readSuggestSettings, realNoticeDeps } from "./status-notices-store";

/**
 * Quick (premade) status notices — admin side. Same permission as Broadcast
 * (area "platform"); every export authorizes FIRST, before touching anything. All
 * behaviour lives in lib/status-notices-core.ts (store-injected, unit-tested).
 * A notice is information only: switching one on never blocks an order.
 */

export type QuickNoticesData = {
  states: Record<string, NoticeCardState>;
  hint: QueueHint;
  suggested: string | null;
  suggestEnabled: boolean;
};

export async function getQuickNoticesData(): Promise<QuickNoticesData> {
  await requireArea("platform");
  const deps = realNoticeDeps();
  const [states, hint, settings] = await Promise.all([
    listNoticeStates(deps),
    queueHint(deps).catch((): QueueHint => ({ active: 0, queued: 0, running: 0, oldestQueuedMinutes: null })),
    readSuggestSettings().catch(() => SUGGEST_DEFAULTS),
  ]);
  return { states, hint, suggested: suggestPreset(hint, settings), suggestEnabled: settings.enabled };
}

export async function setStatusNotice(
  key: string,
  on: boolean,
  opts: SwitchOnOptions = {},
): Promise<{ ok: boolean; error?: string; changed?: boolean }> {
  const admin = await requireArea("platform");
  const deps = realNoticeDeps();
  const res = on ? await switchNoticeOn(deps, admin, key, opts) : await switchNoticeOff(deps, admin, key);
  revalidatePath("/admin/broadcast");
  revalidatePath("/admin/status-notices");
  revalidatePath("/dashboard", "layout");
  revalidatePath("/status");
  return res.ok ? { ok: true, changed: res.changed } : { ok: false, error: res.error };
}

export async function saveStatusNoticeText(
  key: string,
  input: { title?: string; body?: string; reset?: boolean },
): Promise<{ ok: boolean; error?: string }> {
  const admin = await requireArea("platform");
  const res = await saveNoticeText(realNoticeDeps(), admin, key, input);
  revalidatePath("/admin/broadcast");
  revalidatePath("/admin/status-notices");
  return res.ok ? { ok: true } : { ok: false, error: res.error };
}
