"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { saveStatusNoticeText, setStatusNotice, type QuickNoticesData } from "@/lib/actions-status-notices";
import {
  BODY_MAX,
  CATEGORY_LABEL,
  NOTICE_LEVELS,
  NOTICE_PLACEMENTS,
  TITLE_MAX,
  effectiveDismissible,
  presetsByCategory,
  renderBody,
  type NoticePreset,
} from "@/lib/status-notices";
import { CUSTOMER_REGION_LABELS } from "@/lib/node-regions";
import { StatusNoticeBox } from "@/components/customer/StatusNotice";

const HOUR_CHOICES = [1, 2, 4, 6, 12, 24, 48, 72];
const PLACEMENT_LABEL: Record<string, string> = {
  dashboard: "Dashboard banner",
  deploy: "Order flow",
  both: "Dashboard banner + order flow",
};

function hoursLabel(h: number) {
  return h === 1 ? "1 hour" : h < 24 || h % 24 !== 0 ? `${h} hours` : `${h / 24} day${h === 24 ? "" : "s"}`;
}

function ago(iso: string | null) {
  if (!iso) return "";
  const d = new Date(iso);
  return d.toLocaleString("en-US", { dateStyle: "medium", timeStyle: "short" });
}

export function QuickNotices({ data }: { data: QuickNoticesData }) {
  const groups = presetsByCategory();
  const h = data.hint;
  return (
    <section id="quick-notices" className="space-y-5 scroll-mt-20" aria-label="Quick notices">
      <div>
        <h2 className="text-lg font-semibold text-white">Quick notices</h2>
        <p className="mt-1 text-sm text-slate-400">
          Premade customer notices. Switch one on and customers see it straight away; switch it off and it is gone. A notice is
          information only: it never blocks an order. Every switch is recorded in the audit log.
        </p>
      </div>
      {groups.map((g) => (
        <div key={g.category} className="space-y-3" data-category={g.category}>
          <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
            <h3 className="text-sm font-semibold uppercase tracking-wider text-slate-300">{g.label}</h3>
            {g.category === "deployments" && (
              <p className="rounded-lg border border-white/[0.08] bg-white/[0.03] px-3 py-1 text-xs text-slate-300" data-testid="queue-hint">
                <span className="font-semibold text-white">Right now:</span> {h.active} provision job{h.active === 1 ? "" : "s"} queued or running
                {h.queued > 0 ? ` (${h.queued} waiting)` : ""}
                {h.oldestQueuedMinutes !== null ? `, oldest waiting ${h.oldestQueuedMinutes} min` : ", nothing waiting"}
                {data.suggestEnabled ? "" : " . Suggestions are off"}
              </p>
            )}
          </div>
          <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
            {g.presets.map((p) => (
              <NoticeCard key={p.key} preset={p} data={data} suggested={data.suggested === p.key} />
            ))}
          </div>
        </div>
      ))}
    </section>
  );
}

function NoticeCard({ preset, data, suggested }: { preset: NoticePreset; data: QuickNoticesData; suggested: boolean }) {
  const router = useRouter();
  const st = data.states[preset.key];
  const isCustom = preset.category === "custom";
  const on = st?.state === "on";
  const storedTitle = st?.title ?? preset.title;
  const storedBody = st ? st.body : renderBody(preset.body);

  const [pending, start] = useTransition();
  const [err, setErr] = useState("");
  const [hours, setHours] = useState<string>(preset.defaultDurationHours === null ? "" : String(preset.defaultDurationHours));
  const [editing, setEditing] = useState(false);
  const [previewing, setPreviewing] = useState(false);
  const [title, setTitle] = useState(storedTitle);
  const [body, setBody] = useState(isCustom && !st ? "" : storedBody);
  const [windowText, setWindowText] = useState("");
  const [level, setLevel] = useState(st?.level ?? preset.level);
  const [placement, setPlacement] = useState(st?.placement ?? preset.placement);
  const [region, setRegion] = useState(st?.region ?? "");
  const [dismissible, setDismissible] = useState(st?.dismissible ?? preset.dismissible);

  const choices = [...new Set([...(preset.defaultDurationHours ? [preset.defaultDurationHours] : []), ...HOUR_CHOICES])].sort((a, b) => a - b);

  const effLevel = isCustom ? level : preset.level;
  const effPlacement = isCustom ? placement : preset.placement;
  const effDismiss = effectiveDismissible(preset.category, effLevel, isCustom ? dismissible : preset.dismissible);
  const effRegion = isCustom ? region || null : preset.region ?? null;
  const dirty = title !== storedTitle || body !== storedBody;
  // What a customer would read right now (draft text, with the maintenance window filled in).
  const shownBody = preset.hasWindow && windowText.trim() ? renderBody(preset.body, windowText) : body;

  function run(fn: () => Promise<{ ok: boolean; error?: string }>) {
    setErr("");
    start(async () => {
      const r = await fn();
      if (!r.ok) setErr(r.error ?? "Something went wrong.");
      else router.refresh();
    });
  }

  function turnOn() {
    run(() =>
      setStatusNotice(preset.key, true, {
        hours: hours === "" ? null : Number(hours),
        ...(isCustom || dirty || editing ? { title, body: shownBody } : {}),
        ...(preset.hasWindow && windowText.trim() && !dirty ? { windowText } : {}),
        ...(isCustom ? { level, placement, region: region || null, dismissible } : {}),
      }),
    );
  }

  const stateLabel = on ? "ON" : st?.state === "expired" ? "Expired" : "OFF";

  return (
    <div
      data-testid={`notice-card-${preset.key}`}
      data-state={on ? "on" : "off"}
      className={`card flex flex-col gap-3 p-4 ${on ? "ring-1 ring-emerald-400/40" : ""} ${suggested ? "ring-2 ring-amber-400/70" : ""}`}
    >
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <p className="text-sm font-semibold text-white">{preset.label}</p>
          <p className="mt-0.5 text-[11px] text-slate-400">
            {PLACEMENT_LABEL[effPlacement]}
            {preset.region ? ` · ${CUSTOMER_REGION_LABELS[preset.region] ?? preset.region} only` : ""}
            {preset.services ? " · game orders only" : ""} · {effLevel.toLowerCase()}
            {!effDismiss ? " · cannot be dismissed" : ""}
          </p>
        </div>
        <button
          type="button"
          role="switch"
          aria-checked={on}
          aria-label={`${preset.label}: ${on ? "on" : "off"}`}
          disabled={pending || (isCustom && !on && (!title.trim() || !body.trim()))}
          onClick={() => (on ? run(() => setStatusNotice(preset.key, false)) : turnOn())}
          className={`relative h-7 w-[3.25rem] shrink-0 rounded-full border transition-colors disabled:opacity-50 ${
            on ? "border-emerald-400/60 bg-emerald-500/70" : "border-white/15 bg-white/10"
          }`}
        >
          <span className={`absolute top-0.5 h-5 w-5 rounded-full bg-white shadow transition-all ${on ? "left-[1.75rem]" : "left-0.5"}`} />
        </button>
      </div>

      <div className="flex flex-wrap items-center gap-2 text-xs">
        <span
          className={`rounded-md px-2 py-0.5 font-bold tracking-wide ${
            on ? "bg-emerald-500/20 text-emerald-300" : st?.state === "expired" ? "bg-amber-500/15 text-amber-300" : "bg-white/10 text-slate-400"
          }`}
        >
          {stateLabel}
        </span>
        {suggested && <span className="rounded-md bg-amber-500/20 px-2 py-0.5 font-semibold text-amber-200">Suggested by the queue</span>}
        {st?.customized && <span className="rounded-md bg-white/10 px-2 py-0.5 text-slate-300">edited text</span>}
        {st?.switchedAt && (
          <span className="text-slate-500">
            {on ? "Switched on" : "Last changed"} {ago(st.switchedAt)}
            {st.switchedByName ? ` by ${st.switchedByName}` : ""}
          </span>
        )}
      </div>
      {on && st?.expiresAt && <p className="text-xs text-slate-400">Turns off automatically {ago(st.expiresAt)}.</p>}

      {!on && (
        <label className="flex flex-wrap items-center gap-2 text-xs text-slate-400">
          Turn off automatically after
          <select className="input py-1 text-xs" value={hours} onChange={(e) => setHours(e.target.value)} aria-label="Auto-off">
            <option value="">never (until I switch it off)</option>
            {choices.map((c) => (
              <option key={c} value={c}>
                {hoursLabel(c)}
              </option>
            ))}
          </select>
        </label>
      )}

      <p className="line-clamp-3 text-xs text-slate-400">{shownBody || "Write your message."}</p>

      <div className="mt-auto flex gap-4 text-xs">
        <button className="text-slate-200 hover:underline" onClick={() => { setEditing((v) => !v); setPreviewing(false); }}>
          {editing ? "Close editor" : "Edit text"}
        </button>
        <button className="text-slate-200 hover:underline" onClick={() => { setPreviewing((v) => !v); }}>
          {previewing ? "Hide preview" : "Preview"}
        </button>
      </div>

      {editing && (
        <div className="space-y-2 rounded-lg border border-white/[0.08] bg-white/[0.02] p-3" data-testid={`editor-${preset.key}`}>
          <input className="input w-full" value={title} maxLength={TITLE_MAX} onChange={(e) => setTitle(e.target.value)} aria-label="Notice title" placeholder="Title customers see" />
          <textarea className="input w-full" rows={4} value={body} maxLength={BODY_MAX} onChange={(e) => setBody(e.target.value)} aria-label="Notice message" placeholder="Message customers see" />
          {preset.hasWindow && (
            <label className="block text-xs text-slate-400">
              Maintenance window (fills the sentence, for example “tonight between the times you choose”)
              <input className="input mt-1 w-full" value={windowText} onChange={(e) => setWindowText(e.target.value)} placeholder="e.g. on Saturday morning, UTC" aria-label="Maintenance window" />
            </label>
          )}
          {isCustom && (
            <div className="grid grid-cols-2 gap-2 text-xs text-slate-400">
              <label>Level
                <select className="input mt-1 w-full py-1" value={level} onChange={(e) => setLevel(e.target.value)}>
                  {NOTICE_LEVELS.map((l) => <option key={l} value={l}>{l.toLowerCase()}</option>)}
                </select>
              </label>
              <label>Shown in
                <select className="input mt-1 w-full py-1" value={placement} onChange={(e) => setPlacement(e.target.value)}>
                  {NOTICE_PLACEMENTS.map((p) => <option key={p} value={p}>{PLACEMENT_LABEL[p]}</option>)}
                </select>
              </label>
              <label>Only for region
                <select className="input mt-1 w-full py-1" value={region} onChange={(e) => setRegion(e.target.value)}>
                  <option value="">all regions</option>
                  {Object.entries(CUSTOMER_REGION_LABELS).map(([k, v]) => <option key={k} value={k}>{v} ({k})</option>)}
                </select>
              </label>
              <label className="flex items-end gap-2 pb-1">
                <input type="checkbox" checked={dismissible} onChange={(e) => setDismissible(e.target.checked)} /> Customers can dismiss it
              </label>
            </div>
          )}
          <div className="flex flex-wrap gap-3 text-xs">
            <button
              className="btn-primary px-3 py-1"
              disabled={pending || !title.trim() || (isCustom && !body.trim())}
              onClick={() => run(() => saveStatusNoticeText(preset.key, { title, body: shownBody }))}
            >
              Save text{on ? "" : " (stays off)"}
            </button>
            {!isCustom && (
              <button
                className="text-slate-300 hover:underline"
                onClick={() => {
                  setTitle(preset.title);
                  setBody(renderBody(preset.body));
                  run(() => saveStatusNoticeText(preset.key, { reset: true }));
                }}
              >
                Reset to default wording
              </button>
            )}
          </div>
        </div>
      )}

      {previewing && (
        <div className="space-y-3 rounded-lg border border-white/[0.08] bg-navy-950/40 p-3" data-testid={`preview-${preset.key}`}>
          <p className="text-[11px] font-semibold uppercase tracking-wider text-slate-400">What customers will see</p>
          {(effPlacement === "dashboard" || effPlacement === "both") && (
            <div>
              <p className="mb-1 text-[11px] text-slate-500">Dashboard banner{effDismiss ? " (has a dismiss button)" : " (no dismiss button)"}</p>
              <StatusNoticeBox testId="preview-banner" level={effLevel as never} title={title || "Title"} body={shownBody} onDismiss={effDismiss ? () => undefined : undefined} />
            </div>
          )}
          {(effPlacement === "deploy" || effPlacement === "both") && (
            <div>
              <p className="mb-1 text-[11px] text-slate-500">
                Top of the order flow and above Payment{effRegion ? ` (only while ${CUSTOMER_REGION_LABELS[effRegion] ?? effRegion} is selected)` : ""}
              </p>
              <StatusNoticeBox testId="preview-inline" level={effLevel as never} title={title || "Title"} body={shownBody} />
              {preset.category === "deployments" && preset.setup !== false && (
                <>
                  <p className="mb-1 mt-2 text-[11px] text-slate-500">On the “your server is being set up” screen</p>
                  <StatusNoticeBox testId="preview-setup" level={effLevel as never} title={typeof preset.setup === "string" ? preset.setup : title} body={typeof preset.setup === "string" ? null : shownBody} />
                </>
              )}
            </div>
          )}
          <p className="text-[11px] text-slate-500">Also listed on the public status page. Information only: it never blocks an order.</p>
        </div>
      )}

      {err && <p className="text-xs text-red-400" role="alert">{err}</p>}
    </div>
  );
}

