import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments } from "./_source-tools.ts";
import {
  STATUS_NOTICE_PRESETS,
  PRESET_BODY_MAX,
  PRESET_TITLE_MAX,
  presetByKey,
  presetsByCategory,
  effectiveDismissible,
  isLive,
  noticesForDeploy,
  noticesForSetup,
  suggestPreset,
  toCustomerNotice,
  normalizeDuration,
  renderBody,
  type CustomerNotice,
} from "../lib/status-notices.ts";
import {
  listNoticeStates,
  queueHint,
  saveNoticeText,
  switchNoticeOff,
  switchNoticeOn,
  type NoticeDeps,
  type NoticeRow,
  type NoticeStore,
} from "../lib/status-notices-core.ts";

/**
 * Status notices. The persistence logic takes its store and audit writer by injection
 * (lib/status-notices-core.ts), so these tests run the REAL toggle code against an
 * in-memory fake that enforces the same unique templateKey as the schema. Nothing
 * connects to a database. The "use server" action module is checked by source
 * tripwire (every export authorizes with requireArea("platform") first), the repo's
 * convention for modules that import `db`.
 */

const read = (p: string) => stripComments(readFileSync(join(import.meta.dirname, "..", p), "utf8"));

// ---------- fake store ---------------------------------------------------------

function makeFake(opts: { start?: Date } = {}) {
  let clock = opts.start ?? new Date("2026-10-05T12:00:00Z");
  const rows = new Map<string, NoticeRow>();
  let nextId = 1;
  const audits: { actor: string; action: string; detail: string }[] = [];
  const queue = { queued: 0, running: 0, oldestQueuedAt: null as Date | null };
  const store: NoticeStore = {
    async findByKey(k) { return rows.get(k) ?? null; },
    async upsertByKey(k, create, update) {
      const ex = rows.get(k);
      if (ex) { const next = { ...ex, ...update } as NoticeRow; rows.set(k, next); return next; }
      const row: NoticeRow = { id: `n${nextId++}`, templateKey: k, ...create };
      rows.set(k, row);
      return row;
    },
    async listTemplateRows() { return [...rows.values()]; },
    async userNames(ids) { return Object.fromEntries(ids.map((i) => [i, `Admin ${i}`])); },
    async provisionQueue() { return { ...queue }; },
  };
  const deps: NoticeDeps = {
    store,
    audit: async (actor, action, detail) => { audits.push({ actor, action, detail }); },
    now: () => clock,
  };
  return { deps, rows, audits, queue, advance(ms: number) { clock = new Date(clock.getTime() + ms); }, now: () => clock };
}
const admin = { id: "u-admin" };

// ---------- catalog integrity --------------------------------------------------

test("catalog: unique stable keys, required fields, valid enums", () => {
  const keys = STATUS_NOTICE_PRESETS.map((p) => p.key);
  assert.equal(new Set(keys).size, keys.length, "keys are unique");
  assert.ok(STATUS_NOTICE_PRESETS.length >= 16 && STATUS_NOTICE_PRESETS.length <= 26);
  for (const p of STATUS_NOTICE_PRESETS) {
    assert.match(p.key, /^[a-z0-9]+(-[a-z0-9]+)*$/, p.key);
    assert.ok(p.label.trim(), `${p.key} label`);
    assert.ok(["INFO", "SUCCESS", "WARNING", "CRITICAL"].includes(p.level), p.key);
    assert.ok(["dashboard", "deploy", "both"].includes(p.placement), p.key);
    assert.ok(p.defaultDurationHours === null || p.defaultDurationHours > 0, p.key);
  }
  // Every category with presets, and the specific ones the brief names.
  for (const k of ["high-deployment-volume", "provisioning-slower", "game-deployments-delayed", "region-capacity", "deployments-paused",
    "investigating-issue", "degraded-performance", "control-panel-slow", "console-files-slow", "email-delayed", "login-signup-issues",
    "payments-delayed", "local-payments-unavailable", "scheduled-maintenance", "emergency-maintenance", "node-maintenance",
    "support-slower", "all-clear", "custom"]) assert.ok(presetByKey(k), k);
  assert.equal(presetsByCategory().length, 7);
});

test("catalog: per-region variants come from the real region codes", () => {
  const regional = STATUS_NOTICE_PRESETS.filter((p) => p.region);
  assert.deepEqual(regional.map((p) => p.region).sort(), ["bhs1", "fsn1", "sgp1"]);
  const sg = regional.find((p) => p.region === "sgp1")!;
  assert.match(sg.title, /Singapore/);
  assert.match(regional.find((p) => p.region === "bhs1")!.title, /Canada/);
  assert.match(regional.find((p) => p.region === "fsn1")!.title, /Germany/);
  for (const p of regional) { assert.equal(p.placement, "deploy"); assert.equal(p.dismissible, false); }
});

test("catalog: text is short, calm, in Nxeon's voice, with no invented numbers", () => {
  for (const p of STATUS_NOTICE_PRESETS) {
    assert.ok(p.title.trim() && p.body.trim(), `${p.key} has title and body`);
    assert.ok(p.title.length <= PRESET_TITLE_MAX, `${p.key} title ${p.title.length}`);
    assert.ok(p.body.length <= PRESET_BODY_MAX, `${p.key} body ${p.body.length}`);
    const text = `${p.title} ${p.body} ${typeof p.setup === "string" ? p.setup : ""}`;
    assert.ok(!/provider/i.test(text), `${p.key}: never says provider`);
    assert.ok(!/one-?click/i.test(text), `${p.key}: no one-click`);
    assert.ok(!/\d/.test(text), `${p.key}: no digits, so no invented numbers or ETAs`);
    assert.ok(!/!\s/.test(p.body) && !/[\u{1F300}-\u{1FAFF}]/u.test(text), `${p.key}: calm, no emoji`);
  }
});

test("catalog: deployment WARNING/CRITICAL presets are non-dismissible, and the rule is enforced in code", () => {
  for (const p of STATUS_NOTICE_PRESETS.filter((x) => x.category === "deployments" && (x.level === "WARNING" || x.level === "CRITICAL"))) {
    assert.equal(p.dismissible, false, p.key);
  }
  assert.equal(effectiveDismissible("deployments", "WARNING", true), false);
  assert.equal(effectiveDismissible("deployments", "CRITICAL", true), false);
  assert.equal(effectiveDismissible("deployments", "INFO", true), true);
  assert.equal(effectiveDismissible("platform", "WARNING", true), true);
  assert.equal(presetByKey("all-clear")!.level, "SUCCESS");
  assert.equal(presetByKey("all-clear")!.defaultDurationHours, 6);
});

// ---------- toggling -----------------------------------------------------------

test("switch on creates the row from the preset; switching on again is idempotent (one row, unique key)", async () => {
  const f = makeFake();
  const a = await switchNoticeOn(f.deps, admin, "high-deployment-volume");
  assert.ok(a.ok && a.changed);
  assert.equal(f.rows.size, 1);
  const row = f.rows.get("high-deployment-volume")!;
  assert.equal(row.active, true);
  assert.equal(row.templateKey, "high-deployment-volume");
  assert.equal(row.title, presetByKey("high-deployment-volume")!.title);
  assert.equal(row.placement, "both");
  assert.equal(row.switchedBy, admin.id);
  assert.equal(row.createdBy, admin.id);
  const b = await switchNoticeOn(f.deps, admin, "high-deployment-volume");
  assert.ok(b.ok && !b.changed, "already on");
  assert.equal(f.rows.size, 1);
  assert.equal(f.rows.get("high-deployment-volume")!.id, row.id, "same row id");
});

test("concurrent switch-ons end as one row", async () => {
  const f = makeFake();
  await Promise.all([1, 2, 3, 4].map(() => switchNoticeOn(f.deps, admin, "provisioning-slower")));
  assert.equal(f.rows.size, 1);
});

test("switch off deactivates but keeps the row (history); off twice is idempotent", async () => {
  const f = makeFake();
  await switchNoticeOn(f.deps, admin, "payments-delayed");
  const id = f.rows.get("payments-delayed")!.id;
  const off = await switchNoticeOff(f.deps, { id: "u-2" }, "payments-delayed");
  assert.ok(off.ok && off.changed);
  const row = f.rows.get("payments-delayed")!;
  assert.equal(row.active, false);
  assert.equal(row.id, id);
  assert.equal(row.switchedBy, "u-2");
  const again = await switchNoticeOff(f.deps, admin, "payments-delayed");
  assert.ok(again.ok && !again.changed);
  // and it can be reactivated, same row
  await switchNoticeOn(f.deps, admin, "payments-delayed");
  assert.equal(f.rows.size, 1);
  assert.equal(f.rows.get("payments-delayed")!.id, id);
  assert.equal(f.rows.get("payments-delayed")!.active, true);
});

test("switching off a notice that was never on is a safe no-op", async () => {
  const f = makeFake();
  const r = await switchNoticeOff(f.deps, admin, "email-delayed");
  assert.equal(r.ok, false);
  assert.equal(f.rows.size, 0);
});

test("unknown keys are refused and write nothing", async () => {
  const f = makeFake();
  const r = await switchNoticeOn(f.deps, admin, "not-a-notice");
  assert.equal(r.ok, false);
  assert.equal(f.rows.size, 0);
  assert.equal(f.audits.length, 0);
});

test("every toggle writes an audit entry with the actor", async () => {
  const f = makeFake();
  await switchNoticeOn(f.deps, admin, "email-delayed");
  await switchNoticeOff(f.deps, { id: "u-9" }, "email-delayed");
