test("an expired notice is not live and is reported as expired", async () => {
  const f = makeFake();
  await switchNoticeOn(f.deps, admin, "all-clear");
  const row = () => f.rows.get("all-clear")!;
  assert.equal(isLive(row(), f.now()), true);
  assert.equal((await listNoticeStates(f.deps))["all-clear"].state, "on");
  f.advance(6 * 3_600_000 + 1);
  assert.equal(isLive(row(), f.now()), false);
  assert.equal((await listNoticeStates(f.deps))["all-clear"].state, "expired");
  assert.equal(isLive({ active: true, startsAt: new Date(f.now().getTime() + 5000), expiresAt: null }, f.now()), false, "not before startsAt");
  assert.equal(isLive({ active: false, startsAt: null, expiresAt: null }, f.now()), false);
});

// ---------- text ---------------------------------------------------------------

test("edit text before switching on: saved off, kept, then used when switched on", async () => {
  const f = makeFake();
  const saved = await saveNoticeText(f.deps, admin, "provisioning-slower", { title: "Servers are slow", body: "Please bear with us." });
  assert.ok(saved.ok);
  assert.equal(f.rows.get("provisioning-slower")!.active, false, "saving text never switches it on");
  await switchNoticeOn(f.deps, admin, "provisioning-slower");
  const r = f.rows.get("provisioning-slower")!;
  assert.equal(r.title, "Servers are slow");
  assert.equal(r.customText, true);
  assert.equal(r.active, true);
  // survives off/on
  await switchNoticeOff(f.deps, admin, "provisioning-slower");
  await switchNoticeOn(f.deps, admin, "provisioning-slower");
  assert.equal(f.rows.get("provisioning-slower")!.title, "Servers are slow");
  // reset returns the catalog wording
  await saveNoticeText(f.deps, admin, "provisioning-slower", { reset: true });
  const back = f.rows.get("provisioning-slower")!;
  assert.equal(back.title, presetByKey("provisioning-slower")!.title);
  assert.equal(back.customText, false);
});

test("text validation: empty title and over-long text are refused", async () => {
  const f = makeFake();
  assert.equal((await saveNoticeText(f.deps, admin, "email-delayed", { title: "  ", body: "x" })).ok, false);
  assert.equal((await saveNoticeText(f.deps, admin, "email-delayed", { title: "x".repeat(121), body: "x" })).ok, false);
  assert.equal((await saveNoticeText(f.deps, admin, "email-delayed", { title: "x", body: "y".repeat(601) })).ok, false);
  assert.equal(f.rows.size, 0);
});

test("maintenance window fills the body slot and is kept; empty window falls back", async () => {
  const f = makeFake();
  await switchNoticeOn(f.deps, admin, "scheduled-maintenance", { windowText: "on Saturday morning, UTC" });
  assert.match(f.rows.get("scheduled-maintenance")!.body!, /scheduled maintenance on Saturday morning, UTC\./);
  assert.ok(!f.rows.get("scheduled-maintenance")!.body!.includes("{window}"));
  assert.equal(renderBody("a {window} b", ""), "a shortly b");
  await switchNoticeOff(f.deps, admin, "scheduled-maintenance");
  await switchNoticeOn(f.deps, admin, "scheduled-maintenance");
  assert.match(f.rows.get("scheduled-maintenance")!.body!, /Saturday morning/, "window kept on re-enable");
  const f2 = makeFake();
  await switchNoticeOn(f2.deps, admin, "node-maintenance");
  assert.ok(!f2.rows.get("node-maintenance")!.body!.includes("{window}"));
});

test("custom notice needs its own text; level/placement/region are honoured; dismiss rule still applies", async () => {
  const f = makeFake();
  assert.equal((await switchNoticeOn(f.deps, admin, "custom")).ok, false, "no placeholder text can go live");
  const r = await switchNoticeOn(f.deps, admin, "custom", { title: "Hello", body: "World", level: "WARNING", placement: "both", region: "sgp1", dismissible: false });
  assert.ok(r.ok);
  const row = f.rows.get("custom")!;
  assert.deepEqual([row.level, row.placement, row.region, row.dismissible], ["WARNING", "both", "sgp1", false]);
