function notice(key: string, over: Partial<NoticeRow> = {}): CustomerNotice {
  const p = presetByKey(key)!;
  return toCustomerNotice({
    id: key, templateKey: key, level: p.level, title: p.title, body: p.body, placement: p.placement,
    dismissible: p.dismissible, region: p.region ?? null, ...over,
  });
}

