cd /tank/nxeon-wt-notices; cat > .scratch/shots.cjs <<'E'
const { chromium } = require("/opt/nxeon/node_modules/playwright");
const fs = require("fs");
const T = JSON.parse(fs.readFileSync(__dirname + "/tokens.json", "utf8"));
const BASE = "http://localhost:3112";
const OUT = "/root/agent-notes/status-notices";
fs.mkdirSync(OUT, { recursive: true });
const res = [];
const ok = (n, c, d = "") => { res.push(`${c ? "PASS" : "FAIL"} ${n}${d ? " - " + d : ""}`); console.log(res[res.length - 1]); };
(async () => {
  const b = await chromium.launch();
  for (const [w, h, tag] of [[1440, 900, "1440"], [390, 844, "390"]]) {
    const adminCtx = await b.newContext({ viewport: { width: w, height: h } });
    await adminCtx.addCookies([{ name: "nxeon_session", value: T.admin, domain: "localhost", path: "/" }]);
    const a = await adminCtx.newPage();
    a.setDefaultTimeout(60000);
    const errs = [];
    a.on("pageerror", (e) => errs.push(String(e).slice(0, 200)));
    await a.goto(BASE + "/admin/broadcast", { waitUntil: "networkidle" });
    await a.waitForSelector("#quick-notices");
    const card = (k) => a.locator(`[data-testid=notice-card-${k}]`);
    if (tag === "1440") {
      // reset prior state (idempotent reruns): switch off anything on
      for (const k of ["high-deployment-volume", "region-capacity-sgp1", "scheduled-maintenance", "payments-delayed", "provisioning-slower"]) {
        if ((await card(k).getAttribute("data-state")) === "on") { await card(k).getByRole("switch").click(); await a.waitForTimeout(800); }
      }
      // hint
      const hint = await a.locator("[data-testid=queue-hint]").innerText();
      ok("queue hint shows real job counts", /7 provision jobs/.test(hint) && /4 waiting/.test(hint) && /oldest waiting 1[34] min/.test(hint), hint);
      // maintenance window via editor, then ON
      await card("scheduled-maintenance").getByText("Edit text").click();
      await card("scheduled-maintenance").getByLabel("Maintenance window").fill("on Saturday morning, UTC");
      await card("scheduled-maintenance").getByText("Save text").click();
      await a.waitForTimeout(1200);
      for (const k of ["high-deployment-volume", "region-capacity-sgp1", "scheduled-maintenance", "payments-delayed"]) {
        await card(k).getByRole("switch").click();
        await a.waitForFunction((k) => document.querySelector(`[data-testid=notice-card-${k}]`)?.getAttribute("data-state") === "on", k);
      }
      ok("four notices switched on from the UI", (await a.locator("[data-state=on]").count()) === 4);
    }
    await a.locator("#quick-notices").screenshot({ path: `${OUT}/admin-quick-notices-grid-${tag}.png` });
    // edit before enabling
    const c2 = card("provisioning-slower");
    await c2.scrollIntoViewIfNeeded();
    await c2.getByText("Edit text").click();
    await c2.getByLabel("Notice title").fill("Servers are taking a little longer to set up");
    await c2.screenshot({ path: `${OUT}/admin-edit-before-enabling-${tag}.png` });
    // preview
    const c3 = card("game-deployments-delayed");
    await c3.scrollIntoViewIfNeeded();
    await c3.getByText("Preview").click();
    await a.waitForSelector("[data-testid=preview-game-deployments-delayed]");
    await c3.screenshot({ path: `${OUT}/admin-preview-${tag}.png` });
    ok(`admin page no runtime errors (${tag})`, errs.length === 0, errs.join(" | "));
    await adminCtx.close();
  }
  // ---- customer
  for (const [w, h, tag] of [[1440, 900, "1440"], [390, 844, "390"]]) {
    const ctx = await b.newContext({ viewport: { width: w, height: h } });
    await ctx.addCookies([{ name: "nxeon_session", value: T.customer, domain: "localhost", path: "/" }]);
    const p = await ctx.newPage();
    p.setDefaultTimeout(60000);
    const errs = [];
    p.on("pageerror", (e) => errs.push(String(e).slice(0, 200)));
    await p.goto(BASE + "/dashboard", { waitUntil: "networkidle" });
    const banners = await p.locator("[data-testid=dashboard-notice]").allInnerTexts();
    ok(`dashboard banner shows dashboard/both notices (${tag})`, banners.length === 2, banners.map((x) => x.split("\n")[0]).join(" | "));
    ok("banner: region-only deploy notice is NOT on the dashboard", !banners.join().includes("Singapore is at capacity"));
    await p.screenshot({ path: `${OUT}/customer-dashboard-banner-${tag}.png`, clip: { x: 0, y: 0, width: w, height: Math.min(h, 520) } });
    await p.goto(BASE + "/dashboard/deploy?product=vps", { waitUntil: "networkidle" });
    await p.waitForSelector("[data-testid=deploy-notices-top]");
    const top = await p.locator("[data-testid=deploy-notice-top]").allInnerTexts();
    ok(`deploy top notices (${tag})`, top.length >= 2, top.map((x) => x.split("\n")[0]).join(" | "));
    ok("Singapore (default region) notice visible when sgp1 selected", top.join().includes("Singapore is at capacity"));
    await p.screenshot({ path: `${OUT}/customer-deploy-top-${tag}.png` });
    fs.writeFileSync(`${OUT}/.deploy-${tag}.html`, "");
    fs.unlinkSync(`${OUT}/.deploy-${tag}.html`);
    ok(`customer pages no runtime errors (${tag})`, errs.length === 0, errs.join(" | "));
    await ctx.close();
  }
  await b.close();
  fs.writeFileSync(OUT + "/results-part1.txt", res.join("\n") + "\n");
})();
E
node .scratch/shots.cjs 2>&1 | tail -30

