"use client";

import { useState } from "react";
import { NOTICES_VISIBLE, sortNotices, type NoticeLevel } from "@/lib/status-notices";

/**
 * Status notices as a customer sees them. The admin preview renders these exact
 * components, so "Preview" cannot drift from what ships. Information only: nothing
 * here blocks anything it sits next to.
 *
 * Compact on purpose: one slim row, bold title with the message on the same line where
 * it fits (about two lines on desktop), and a surface never shows more than
 * NOTICES_VISIBLE notices expanded. The rest collapse into one "N more notices" line.
 *
 * role: CRITICAL is `alert` (announced immediately); everything else is `status`
 * (polite). Notices arrive in the server-rendered HTML, so they take their space on
 * first paint and nothing below them jumps.
 */
const TONE: Record<NoticeLevel, { box: string; dot: string }> = {
  INFO: { box: "border-brand-500/30 bg-brand-500/[0.08] text-brand-100", dot: "bg-brand-400" },
  SUCCESS: { box: "border-emerald-500/30 bg-emerald-500/[0.08] text-emerald-100", dot: "bg-emerald-400" },
  WARNING: { box: "border-amber-500/30 bg-amber-500/[0.08] text-amber-100", dot: "bg-amber-400" },
  CRITICAL: { box: "border-red-500/30 bg-red-500/[0.08] text-red-100", dot: "bg-red-400" },
};

export function StatusNoticeBox({
  level,
  title,
  body,
  onDismiss,
  className = "",
  testId,
}: {
  level: NoticeLevel;
  title: string;
  body?: string | null;
  /** Present only when the notice is dismissible. */
  onDismiss?: () => void;
  className?: string;
  testId?: string;
}) {
  const t = TONE[level] ?? TONE.INFO;
  return (
    <div
      role={level === "CRITICAL" ? "alert" : "status"}
      data-testid={testId ?? "status-notice"}
      className={`flex items-start justify-between gap-2 rounded-lg border px-3 py-2 text-[13px] leading-[1.45] ${t.box} ${className}`}
    >
      <div className="flex min-w-0 items-start gap-2.5">
        <span aria-hidden className={`mt-[7px] h-1.5 w-1.5 shrink-0 rounded-full ${t.dot}`} />
        <p className="min-w-0">
          <span className="font-semibold">{title}</span>
          {body ? <span className="opacity-90">{" "}{body}</span> : null}
        </p>
      </div>
      {onDismiss ? (
        <button aria-label="Dismiss" className="-my-0.5 shrink-0 rounded px-1 py-0.5 opacity-70 transition-opacity hover:opacity-100" onClick={onDismiss}>
          ✕
        </button>
      ) : null}
    </div>
  );
}

export type StackItem = {
  id: string;
  level: NoticeLevel;
  title: string;
  body: string | null;
  /** Only meaningful with onDismiss on the stack. */
  dismissible?: boolean;
};

/**
 * A capped list: most important first (CRITICAL, non-dismissible, WARNING, INFO), at most
 * NOTICES_VISIBLE expanded, the rest behind a single slim "N more notices" toggle.
 */
export function NoticeStack({
  items,
  onDismiss,
  testId,
  className = "",
}: {
  items: StackItem[];
  onDismiss?: (id: string) => void;
  testId: string;
  className?: string;
}) {
  const [open, setOpen] = useState(false);
  if (items.length === 0) return null;
  const sorted = sortNotices(items.map((n) => ({ ...n, dismissible: n.dismissible ?? true })));
  const shown = sorted.slice(0, NOTICES_VISIBLE);
  const rest = sorted.slice(NOTICES_VISIBLE);
  const row = (n: (typeof sorted)[number]) => (
    <StatusNoticeBox
      key={n.id}
      testId={testId}
      level={n.level}
      title={n.title}
      body={n.body}
      onDismiss={onDismiss && n.dismissible ? () => onDismiss(n.id) : undefined}
    />
  );
  return (
    <div className={`space-y-1.5 ${className}`}>
      {shown.map(row)}
      {rest.length > 0 && !open && (
        <button
          type="button"
          aria-expanded={false}
          data-testid={`${testId}-more`}
          onClick={() => setOpen(true)}
          className="w-full rounded-lg border border-white/[0.08] bg-white/[0.03] px-3 py-1.5 text-left text-[12.5px] font-medium text-slate-300 hover:bg-white/[0.06]"
        >
          {rest.length} more notice{rest.length === 1 ? "" : "s"} <span aria-hidden>▾</span>
        </button>
      )}
      {open && rest.map(row)}
      {open && rest.length > 0 && (
        <button
          type="button"
          aria-expanded
          onClick={() => setOpen(false)}
          className="w-full rounded-lg px-3 py-1 text-left text-[12px] text-slate-400 hover:text-slate-200"
        >
          Show fewer <span aria-hidden>▴</span>
        </button>
      )}
    </div>
  );
}
