open(p,'w').write('''"use client";

import { useState } from "react";
import { usePathname } from "next/navigation";
import { dismissAnnouncement, type AnnouncementView } from "@/lib/actions-broadcast";
import { NoticeStack } from "./StatusNotice";

/** Dismissible admin broadcasts, shown at the top of the customer portal. Each
 *  dismissal is persisted per-user (server-side), so it stays gone across pages
 *  and devices. Optimistic: it disappears immediately, then records the dismissal.
 *
 *  A customer must never see the same notice twice. On the order flow
 *  (/dashboard/deploy) the wizard renders its own inline copy of every deploy/both
 *  notice, so the banner skips those there; on a server page the setup screen does
 *  the same for the deployment notices that have a setup sentence. */
export function AnnouncementBanner({ announcements }: { announcements: AnnouncementView[] }) {
  const [hidden, setHidden] = useState<Set<string>>(new Set());
  const path = usePathname() ?? "";
  const onOrderFlow = path.startsWith("/dashboard/deploy");
  const onServerPage = /^\\/dashboard\\/servers\\/[^/]+/.test(path);
  const visible = announcements.filter((a) => {
    if (hidden.has(a.id)) return false;
    if (onOrderFlow && a.placement !== "dashboard") return false;
    if (onServerPage && a.hasSetupSentence) return false;
    return true;
  });
  if (visible.length === 0) return null;

  return (
    <NoticeStack
      className="mb-4"
      testId="dashboard-notice"
