  const admin = await db.user.upsert({ where: { email: "admin@sandbox.test" }, update: { role: "ADMIN" }, create: { email: "admin@sandbox.test", passwordHash: "x", name: "Sandbox Admin", role: "ADMIN" } });
  const cust = await db.user.upsert({ where: { email: "cust@sandbox.test" }, update: {}, create: { email: "cust@sandbox.test", passwordHash: "x", name: "Alex Customer", role: "CUSTOMER", emailVerifiedAt: new Date(), balanceCents: 5000, heardAboutUs: "other" } as never });
