  await db.osTemplate.upsert({ where: { slug: "debian-13" }, update: {}, create: { slug: "debian-13", name: "Debian 13", vmid: 9001 } });
  let sg;
  for (const n of [["sgp-1", "sgp1", "OVH", true, "203.0.113.10"], ["bhs-1", "bhs1", "OVH", false, "203.0.113.11"], ["fsn-1", "fsn1", "HETZNER", false, "203.0.113.12"]] as const) {
    const row = await db.node.upsert({ where: { name: n[0] }, update: {}, create: { name: n[0], pveNode: n[0], apiUrl: "https://127.0.0.1:1", tokenId: "x", tokenSecret: "x", publicIp: n[4], region: n[1], provider: n[2], isPrimary: n[3] } as never });
    if (n[1] === "sgp1") sg = row;
  }
  const plan = await db.plan.findFirstOrThrow({ where: { slug: "starter" } });
  let srv = await db.server.findFirst({ where: { userId: cust.id } });
  if (!srv) srv = await db.server.create({ data: { name: "my-first-server", hostname: "my-first-server", userId: cust.id, planId: plan.id, osTemplateId: os.id, status: "PROVISIONING", nodeId: sg!.id } as never });
  const deps = { store: dbNoticeStore, audit: async () => {}, now: () => new Date() };
  for (const k of ["provisioning-slower", "high-deployment-volume", "region-capacity-sgp1", "payments-delayed", "scheduled-maintenance", "email-delayed", "support-slower"]) {
    const r = await switchNoticeOn(deps, admin, k, k === "scheduled-maintenance" ? { windowText: "on Saturday morning, UTC" } : {});
    if (!r.ok) throw new Error(r.error);
  }
  writeFileSync(__dirname + "/tokens.json", JSON.stringify({ admin: await tok(admin.id), customer: await tok(cust.id), serverId: srv.id }));
  await db.$disconnect();
  console.log("seeded");
