cd /tank/nxeon-wt-notices; cat > .scratch/shots2.cjs <<'E'
const { chromium } = require("/opt/nxeon/node_modules/playwright");
const fs = require("fs");
const T = JSON.parse(fs.readFileSync(__dirname + "/tokens.json", "utf8"));
const BASE = "http://localhost:3112", OUT = "/root/agent-notes/status-notices/v2";
fs.mkdirSync(OUT, { recursive: true });
const res = [];
const ok = (n, c, d = "") => { res.push(`${c ? "PASS" : "FAIL"} ${n}${d ? " - " + d : ""}`); console.log(res[res.length - 1]); };
(async () => {
  const b = await chromium.launch();
  for (const [w, h, tag] of [[1440, 900, "1440"], [390, 844, "390"]]) {
    const ctx = await b.newContext({ viewport: { width: w, height: h } });
    await ctx.addCookies([{ name: "nxeon_session", value: T.customer, domain: "localhost", path: "/" }]);
    const p = await ctx.newPage(); p.setDefaultTimeout(60000);
    const cookie = async () => p.getByRole("button", { name: "Got it" }).click({ timeout: 2500 }).catch(() => {});
    // dashboard: 6 dashboard/both notices -> 2 shown + "4 more"
    await p.goto(BASE + "/dashboard", { waitUntil: "networkidle" }); await cookie();
    const d1 = await p.locator("[data-testid=dashboard-notice]").evaluateAll((e) => e.map((x) => x.querySelector("span.font-semibold").textContent));
    const more = await p.locator("[data-testid=dashboard-notice-more]").innerText();
    ok(`dashboard capped at 2 + collapsed line (${tag})`, d1.length === 2 && /4 more notices/.test(more), d1.join(" | ") + " / " + more);
    ok("most important first (non-dismissible warning before info)", /longer to set up|slower than usual/i.test(d1[0]) || d1[0].includes("Provisioning"), d1[0]);
    await p.screenshot({ path: `${OUT}/dashboard-collapsed-${tag}.png`, clip: { x: 0, y: 0, width: w, height: 420 } });
    await p.locator("[data-testid=dashboard-notice-more]").click();
    ok("expands on click", (await p.locator("[data-testid=dashboard-notice]").count()) === 6);
    await p.screenshot({ path: `${OUT}/dashboard-expanded-${tag}.png`, clip: { x: 0, y: 0, width: w, height: Math.min(900, 800) } });
    // deploy flow: banner must not repeat inline notices
    await p.goto(BASE + "/dashboard/deploy?product=vps&plan=starter&region=sgp1&step=configure", { waitUntil: "networkidle" }); await cookie();
    await p.getByRole("button", { name: /Configure/ }).first().click().catch(() => {});
    await p.waitForTimeout(900); await p.evaluate(() => window.scrollTo(0, 0));
    const banner = await p.locator("[data-testid=dashboard-notice]").evaluateAll((e) => e.map((x) => x.querySelector("span.font-semibold").textContent));
    const inline = await p.locator("[data-testid=deploy-notice-top], [data-testid=deploy-notice-pay]").evaluateAll((e) => e.map((x) => x.querySelector("span.font-semibold").textContent));
    const all = [...banner, ...inline];
    ok(`deploy flow: no notice appears twice (${tag})`, new Set(all).size === all.length, `banner=[${banner}] inline=[${inline}]`);
    ok("deploy flow: banner only has dashboard-only notices", banner.every((t) => /Support|Email/.test(t)) , banner.join(" | "));
    await p.screenshot({ path: `${OUT}/deploy-flow-${tag}.png` });
    // pay step
    await p.goto(BASE + "/dashboard/deploy?product=vps&plan=starter&region=sgp1", { waitUntil: "networkidle" }); await cookie();
    await p.waitForSelector("[data-testid=deploy-notice-pay]");
    await p.evaluate(() => document.querySelector("#s-payment").scrollIntoView({ block: "start" })); await p.waitForTimeout(500);
    const pay = await p.locator("[data-testid=deploy-notice-pay]").count();
    ok(`pay step shows 2 + a more line (${tag})`, pay === 2 && (await p.locator("[data-testid=deploy-notice-pay-more]").count()) === 1, String(pay));
    await p.screenshot({ path: `${OUT}/deploy-pay-step-${tag}.png` });
    // setup screen
    await p.goto(BASE + "/dashboard/servers/" + T.serverId, { waitUntil: "networkidle" }); await cookie();
    await p.waitForSelector("[data-testid=setup-notices]");
    const sb = await p.locator("[data-testid=dashboard-notice]").evaluateAll((e) => e.map((x) => x.querySelector("span.font-semibold").textContent));
    const su = await p.locator("[data-testid=setup-notice]").evaluateAll((e) => e.map((x) => x.querySelector("span.font-semibold").textContent));
    ok(`setup screen: sentence once, deployment notices not repeated in banner (${tag})`, su.filter((t) => /being set up/.test(t)).length === 1 && !sb.some((t) => /Provisioning|High deployment/.test(t)), `banner=[${sb}] setup=[${su}]`);
    await p.screenshot({ path: `${OUT}/setup-screen-${tag}.png` });
    await ctx.close();
  }
  await b.close();
})();
E
node .scratch/shots2.cjs > /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/s2.out 2>&1 &
sleep 100; cat /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/s2.out

